      "qualname": "funcy/calc.py::memoize",
      "source": "def memoize(*args, **kwargs):
    """@memoize(key_func=None). Makes decorated function memoize its results.

    If key_func is specified uses key_func(*func_args, **func_kwargs) as memory key.
    Otherwise uses args + tuple(sorted(kwargs.items()))

    Exposes its memory via .memory attribute.
    """
    if args:
        assert len(args) == 1 and not kwargs
        return memoize()(args[0])
    key_func = kwargs.pop('key_func', None) or (lambda *a, **kw: a + tuple(sorted(kw.items())) if kw else a)
    if kwargs:
        raise TypeError('memoize() got unexpected keyword arguments: %s', ', '.join(kwargs))

    def decorator(func):
        mem = {}
        @wraps(func)
        def wrapper(*a, **kw):
            k = key_func(*a, **kw)
            try:
                return mem[k]
            except KeyError:
                try:
                    v = mem[k] = func(*a, **kw)
                    return v
                except SkipMemoization as e:
                    return e.args[0] if e.args else None
        wrapper.memory = mem
        wrapper.skip = SkipMemoization
        wrapper.invalidate = lambda *a, **kw: mem.pop(key_func(*a, **kw), None)
        wrapper.invalidate_all = lambda: mem.clear()
        return wrapper
    return decorator"
    },
