      "qualname": "funcy/calc.py::cache",
      "source": "def cache(timeout, key_func=None):
    """Caches a function results for timeout seconds."""
    timeout = timedelta(seconds=timeout) if isinstance(timeout, int) else timeout
    key_func = key_func or (lambda *a, **kw: a + tuple(sorted(kw.items())) if kw else a)

    def decorator(func):
        c = {}
        @wraps(func)
        def wrapper(*a, **kw):
            k = key_func(*a, **kw)
            now = datetime.now()
            if k in c:
                r, t = c[k]
                if now - t < timeout:
                    return r
                del c[k]
            r = func(*a, **kw)
            c[k] = r, now
            return r
        wrapper.memory = c
        wrapper.skip = SkipMemoization
        wrapper.invalidate = lambda *a, **kw: c.pop(key_func(*a, **kw), None)
        wrapper.invalidate_all = lambda: c.clear()
        return wrapper
    return decorator"
